    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
    background: #f5f7fa;
    color: #1a202c;
    line-height: 1.6;
  }}
  .container {{ max-width: 1280px; margin: 0 auto; padding: 0 24px; }}
  header {{
    background: linear-gradient(135deg, #006a4e 0%, #00a86b 100%);
    color: white;
    padding: 56px 0 48px;
    border-bottom: 4px solid #f42a41;
  }}
  header h1 {{ font-size: 2.2rem; font-weight: 700; margin-bottom: 10px; }}
  header .subtitle {{ font-size: 1.05rem; opacity: 0.92; max-width: 900px; }}
  header .meta {{ margin-top: 18px; font-size: 0.85rem; opacity: 0.82; }}
  .section {{ margin: 48px 0; }}
  .section-title {{
    font-size: 1.55rem;
    color: #006a4e;
    margin-bottom: 8px;
    padding-bottom: 8px;
    border-bottom: 2px solid #e0e6ed;
  }}
  .section-objective {{
    color: #4a5568;
    font-size: 0.95rem;
    margin-bottom: 24px;
    font-style: italic;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 12px;
  }}
  .kpi-card {{
    background: white;
    padding: 22px 20px;
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    border-left: 4px solid #006a4e;
    position: relative;
  }}
  .kpi-card.warning {{ border-left-color: #f59e0b; }}
  .kpi-card.danger {{ border-left-color: #ef4444; }}
  .kpi-card.success {{ border-left-color: #10b981; }}
  .kpi-label {{
    font-size: 0.8rem;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
  }}
  .kpi-value {{
    font-size: 2rem;
    font-weight: 700;
    color: #1a202c;
    line-height: 1.1;
  }}
  .kpi-unit {{ font-size: 1.1rem; font-weight: 500; color: #64748b; margin-left: 4px; }}
  .kpi-desc {{ font-size: 0.8rem; color: #64748b; margin-top: 6px; }}
  .card {{
    background: white;
    padding: 24px;
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
    margin-bottom: 20px;
  }}
  .grid-2 {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .grid-3 {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }}
  @media (max-width: 780px) {{
    .grid-2, .grid-3 {{ grid-template-columns: 1fr; }}
  }}
  .chart-container {{ position: relative; height: 320px; }}
  .chart-container.tall {{ height: 420px; }}
  h3 {{ font-size: 1.1rem; color: #2d3748; margin-bottom: 16px; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 0.9rem; }}
  th {{
    background: #f1f5f9;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    color: #475569;
    border-bottom: 2px solid #cbd5e1;
  }}
  td {{ padding: 9px 12px; border-bottom: 1px solid #e2e8f0; }}
  tr:hover td {{ background: #f8fafc; }}
  .heat {{ display: inline-block; padding: 3px 10px; border-radius: 4px; font-weight: 600; font-size: 0.85rem; }}
  .insight {{
    background: #eff6ff;
    border-left: 4px solid #3b82f6;
    padding: 16px 20px;
    margin: 16px 0;
    border-radius: 0 6px 6px 0;
  }}
  .insight strong {{ color: #1e40af; }}
  .warning-box {{
    background: #fef3c7;
    border-left: 4px solid #f59e0b;
    padding: 16px 20px;
    margin: 16px 0;
    border-radius: 0 6px 6px 0;
  }}
  .warning-box strong {{ color: #92400e; }}
  .rec-list {{ list-style: none; }}
  .rec-list li {{
    background: white;
    padding: 18px 22px;
    margin-bottom: 12px;
    border-radius: 8px;
    border-left: 4px solid #006a4e;
    box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  }}
  .rec-list li strong {{ color: #006a4e; display: block; margin-bottom: 6px; font-size: 1.05rem; }}
  footer {{
    background: #1a202c;
    color: #cbd5e1;
    padding: 30px 0;
    margin-top: 60px;
    text-align: center;
    font-size: 0.85rem;
  }}
  .heatmap-row {{ display: flex; align-items: center; margin-bottom: 4px; }}
  .heatmap-label {{ width: 120px; font-size: 0.9rem; }}
  .heatmap-bar {{ flex: 1; height: 28px; position: relative; background: #e2e8f0; border-radius: 4px; overflow: hidden; }}
  .heatmap-fill {{ height: 100%; display: flex; align-items: center; padding-left: 10px; color: white; font-weight: 600; font-size: 0.85rem; }}
</style>
</head>
<body>

<header>
  <div class="container">
    <h1>Student Performance Analytics Report</h1>
    <div class="subtitle">Factors Influencing Academic Outcomes in Bangladesh — A Comprehensive Analysis of {d['total']:,} Students Across 8 Districts</div>
    <div class="meta">Prepared for education policy analysts and school administrators · Dataset: Bangladesh Student Performance (HSC/SSC) · N = {d['total']:,}</div>
  </div>
</header>

<div class="container">

<!-- ═══ EXECUTIVE KPI DASHBOARD ═══ -->
<section class="section">
  <h2 class="section-title">Executive KPI Dashboard</h2>
  <p class="section-objective">At-a-glance indicators of system-wide student performance on the 0–5 GPA scale.</p>
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Average HSC Result</div>
      <div class="kpi-value">{k['avg_hsc']}<span class="kpi-unit">/5.0</span></div>
      <div class="kpi-desc">Mean GPA across all {d['total']:,} students</div>
    </div>
    <div class="kpi-card success">
      <div class="kpi-label">Excellent Performance Rate</div>
      <div class="kpi-value">{k['excellent_rate']}<span class="kpi-unit">%</span></div>
      <div class="kpi-desc">Students scoring HSC ≥ 4.5 ({int(k['excellent_rate']*d['total']/100)} students)</div>
    </div>
    <div class="kpi-card success">
      <div class="kpi-label">At-Risk Student Rate</div>
      <div class="kpi-value">{k['at_risk_rate']}<span class="kpi-unit">%</span></div>
      <div class="kpi-desc">Students with HSC &lt; 3.0 — no students below this threshold</div>
    </div>
    <div class="kpi-card {'success' if k['gpa_delta'] >= 0 else 'warning'}">
      <div class="kpi-label">GPA Progression Delta</div>
      <div class="kpi-value">{'+' if k['gpa_delta']>=0 else ''}{k['gpa_delta']}</div>
      <div class="kpi-desc">Avg HSC − Previous GPA (essentially flat)</div>
    </div>
    <div class="kpi-card warning">
      <div class="kpi-label">Attendance–Performance Correlation</div>
      <div class="kpi-value">{k['attendance_corr']}</div>
      <div class="kpi-desc">Pearson r — negligible relationship</div>
    </div>
  </div>
  <div class="insight">
    <strong>Executive Summary:</strong> Average HSC performance is solid at {k['avg_hsc']}/5.0, with {k['excellent_rate']}% of students achieving excellence (GPA ≥ 4.5) and a 100% pass rate. Critically, <strong>traditional drivers (attendance, income, internet access, private tuition) show near-zero correlation with HSC outcomes in this cohort</strong> — a finding that challenges common assumptions and warrants deeper investigation. Regional variation is the single largest observable disparity, with Barisal ({reg['district_hsc'][0]['mean_hsc']:.2f}) outperforming Rangpur ({reg['district_hsc'][-1]['mean_hsc']:.2f}) by 0.20 GPA points.
  </div>
</section>

<!-- ═══ SECTION 1: DEMOGRAPHIC OVERVIEW ═══ -->
<section class="section">
  <h2 class="section-title">1. Student Demographic Overview</h2>
  <p class="section-objective">Composition of the 1,000-student cohort by gender, age, district, and school type.</p>
  <div class="grid-2">
    <div class="card"><h3>Gender Distribution</h3><div class="chart-container"><canvas id="genderChart"></canvas></div></div>
    <div class="card"><h3>Age Distribution</h3><div class="chart-container"><canvas id="ageChart"></canvas></div></div>
  </div>
  <div class="grid-2">
    <div class="card"><h3>District Representation</h3><div class="chart-container"><canvas id="districtChart"></canvas></div></div>
    <div class="card"><h3>School Type</h3><div class="chart-container"><canvas id="schoolTypeChart"></canvas></div></div>
  </div>
  <div class="insight">
    <strong>Key observation:</strong> The sample is well-balanced: {d['gender']['Female']} female ({d['gender']['Female']/10:.1f}%) and {d['gender']['Male']} male ({d['gender']['Male']/10:.1f}%) students, distributed across eight administrative divisions with no single district exceeding {max(d['district'].values())/10:.1f}% representation. Private schools slightly outnumber public ({d['school_type']['Private']} vs {d['school_type']['Public']}), enabling fair institutional comparison.
  </div>
</section>

<!-- ═══ SECTION 2: ACADEMIC PERFORMANCE ═══ -->
<section class="section">
  <h2 class="section-title">2. Academic Performance Analysis</h2>
  <p class="section-objective">Distribution and progression of GPAs across Previous, SSC, and HSC examinations.</p>

  <div class="grid-2">
    <div class="card">
      <h3>GPA Means Across Academic Milestones</h3>
      <div class="chart-container"><canvas id="gpaComparisonChart"></canvas></div>
    </div>
    <div class="card">
      <h3>HSC Performance Classification</h3>
      <div class="chart-container"><canvas id="perfHscChart"></canvas></div>
    </div>
  </div>

  <div class="card">
    <h3>Summary Statistics by Examination</h3>
    <table>
      <thead><tr><th>Examination</th><th>Mean</th><th>Median</th><th>Std Dev</th><th>Min</th><th>Max</th></tr></thead>
      <tbody>
        <tr><td>Previous GPA</td><td>{a['gpa_stats']['Previous_GPA']['mean']}</td><td>{a['gpa_stats']['Previous_GPA']['median']}</td><td>{a['gpa_stats']['Previous_GPA']['std']}</td><td>{a['gpa_stats']['Previous_GPA']['min']}</td><td>{a['gpa_stats']['Previous_GPA']['max']}</td></tr>
        <tr><td>SSC Result</td><td>{a['gpa_stats']['SSC_Result']['mean']}</td><td>{a['gpa_stats']['SSC_Result']['median']}</td><td>{a['gpa_stats']['SSC_Result']['std']}</td><td>{a['gpa_stats']['SSC_Result']['min']}</td><td>{a['gpa_stats']['SSC_Result']['max']}</td></tr>
        <tr><td><strong>HSC Result</strong></td><td><strong>{a['gpa_stats']['HSC_Result']['mean']}</strong></td><td>{a['gpa_stats']['HSC_Result']['median']}</td><td>{a['gpa_stats']['HSC_Result']['std']}</td><td>{a['gpa_stats']['HSC_Result']['min']}</td><td>{a['gpa_stats']['HSC_Result']['max']}</td></tr>
      </tbody>
    </table>
  </div>

  <div class="grid-2">
    <div class="card">
      <h3>GPA Progression Trajectory (Previous → HSC)</h3>
      <div class="chart-container"><canvas id="progressionChart"></canvas></div>
    </div>
    <div class="card">
      <h3>Progression Narrative</h3>
      <p style="margin-bottom:12px">The <strong>GPA Progression Delta</strong> — defined as HSC Result minus Previous GPA — averages <strong>{a['avg_delta_prev_hsc']:+.3f}</strong> points. This near-zero aggregate masks a polarized distribution:</p>
      <ul style="padding-left:20px;margin-bottom:12px">
        <li><strong>{a['improving_pct']}%</strong> of students improved their GPA from pre-HSC to HSC</li>
        <li><strong>{a['declining_pct']}%</strong> saw a decline — nearly a coin flip</li>
        <li><strong>{a['stable_pct']}%</strong> held steady</li>
      </ul>
      <p>Notably, the SSC → HSC transition shows a <strong>{a['avg_delta_ssc_hsc']:+.3f}</strong> average drop, suggesting HSC is a harder examination than SSC — or that preparation intensity declines after SSC.</p>
    </div>
  </div>

  <div class="insight">
    <strong>Finding:</strong> The floor of HSC Results is 3.00, meaning <strong>every student in the cohort passed</strong> (pass threshold 2.0). The concern is not failure but stagnation: mean HSC (4.01) falls below mean SSC (4.26), indicating systemic underperformance at the higher-secondary stage.
  </div>
</section>

<!-- ═══ SECTION 3: SOCIO-ECONOMIC (CRITICAL) ═══ -->
<section class="section">
  <h2 class="section-title">3. Socio-Economic Factors and Their Impact on Performance</h2>
  <p class="section-objective">Quantifying the relationship between family income, parent education, internet access, and private tuition vs. HSC outcomes — the critical focus of this report.</p>

  <div class="warning-box">
    <strong>Headline finding (data-driven, not a priori):</strong> Across all four socio-economic dimensions analyzed, <strong>effect sizes are uniformly small</strong> (all |Cohen's d| &lt; 0.1). Mean HSC GPAs differ by less than 0.1 points between the most and least advantaged groups. This contradicts the prevailing assumption that socio-economic advantage strongly determines HSC outcomes in this cohort — and demands careful interpretation below.
  </div>

  <div class="grid-2">
    <div class="card">
      <h3>HSC Mean by Family Income Quartile</h3>
      <div class="chart-container"><canvas id="incomeQuartileChart"></canvas></div>
    </div>
    <div class="card">
      <h3>HSC Mean by Parent Education Level</h3>
      <div class="chart-container"><canvas id="parentEdChart"></canvas></div>
    </div>
  </div>

  <div class="card">
    <h3>Detailed Breakdown: Family Income</h3>
    <table>
      <thead><tr><th>Income Quartile</th><th>Range (BDT)</th><th>N</th><th>Mean HSC</th><th>Std Dev</th><th>Excellent Rate</th></tr></thead>
      <tbody>"""

for i, row in enumerate(s['income_by_quartile']):
    rng = s['income_ranges'][i]
    q_label = row['quartile']
    exc = s['excellent_by_income'].get(q_label, 0)
    html += f"""
        <tr><td>{q_label}</td><td>{rng['min']:,} – {rng['max']:,}</td><td>{row['count']}</td><td><strong>{row['mean_hsc']:.3f}</strong></td><td>{row['std_hsc']:.3f}</td><td>{exc}%</td></tr>"""

html += f"""
      </tbody>
    </table>
    <p style="margin-top:14px;color:#475569;font-size:0.9rem"><strong>Income–HSC Pearson r = {s['income_corr']}</strong> · <strong>Cohen's d (Q4 vs Q1) = {s['cohen_d_income']}</strong> → statistically negligible. Students from the highest-income quartile actually perform <em>marginally lower</em> on average than those from the lowest quartile.</p>
  </div>

  <div class="card">
    <h3>Detailed Breakdown: Parent Education</h3>
    <table>
      <thead><tr><th>Parent Education</th><th>N</th><th>Mean HSC</th><th>Std Dev</th><th>Excellent Rate</th></tr></thead>
      <tbody>"""

for row in s['parent_ed_hsc']:
    exc = s['excellent_by_parent_ed'].get(row['education'], 0)
    html += f"""
        <tr><td>{row['education']}</td><td>{row['count']}</td><td><strong>{row['mean_hsc']:.3f}</strong></td><td>{row['std_hsc']:.3f}</td><td>{exc}%</td></tr>"""

html += f"""
      </tbody>
    </table>
    <p style="margin-top:14px;color:#475569;font-size:0.9rem"><strong>Cohen's d (Graduate vs Primary) = {s['cohen_d_parent_ed']}</strong>. Children of Secondary-educated parents ({s['parent_ed_hsc'][1]['mean_hsc']:.2f}) actually posted the highest mean, followed by Higher Secondary ({s['parent_ed_hsc'][2]['mean_hsc']:.2f}). Graduate-parent students ({s['parent_ed_hsc'][3]['mean_hsc']:.2f}) did not outperform — a counter-intuitive pattern worth policy attention.</p>
  </div>

  <div class="grid-2">
    <div class="card">
      <h3>Internet Access Impact</h3>
      <table>
        <thead><tr><th>Access</th><th>N</th><th>Mean HSC</th><th>Std Dev</th></tr></thead>
        <tbody>
          <tr><td>Yes</td><td>{s['internet_hsc'][1]['count']}</td><td><strong>{s['internet_hsc'][1]['mean_hsc']:.3f}</strong></td><td>{s['internet_hsc'][1]['std_hsc']:.3f}</td></tr>
          <tr><td>No</td><td>{s['internet_hsc'][0]['count']}</td><td><strong>{s['internet_hsc'][0]['mean_hsc']:.3f}</strong></td><td>{s['internet_hsc'][0]['std_hsc']:.3f}</td></tr>
          <tr style="background:#f8fafc"><td colspan="4"><strong>Difference:</strong> +{s['internet_hsc'][1]['mean_hsc']-s['internet_hsc'][0]['mean_hsc']:.3f} GPA · <strong>Cohen's d = {s['cohen_d_internet']}</strong> (trivial)</td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <h3>Private Tuition Impact</h3>
      <table>
        <thead><tr><th>Tuition</th><th>N</th><th>Mean HSC</th><th>Std Dev</th></tr></thead>
        <tbody>
          <tr><td>Yes</td><td>{s['tuition_hsc'][1]['count']}</td><td><strong>{s['tuition_hsc'][1]['mean_hsc']:.3f}</strong></td><td>{s['tuition_hsc'][1]['std_hsc']:.3f}</td></tr>
          <tr><td>No</td><td>{s['tuition_hsc'][0]['count']}</td><td><strong>{s['tuition_hsc'][0]['mean_hsc']:.3f}</strong></td><td>{s['tuition_hsc'][0]['std_hsc']:.3f}</td></tr>
          <tr style="background:#f8fafc"><td colspan="4"><strong>Difference:</strong> +{s['tuition_hsc'][1]['mean_hsc']-s['tuition_hsc'][0]['mean_hsc']:.3f} GPA · <strong>Cohen's d = {s['cohen_d_tuition']}</strong> (trivial)</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <div class="insight">
    <strong>Interpretation:</strong> The absence of strong socio-economic effects has two plausible explanations:
    <ol style="margin-top:8px;padding-left:24px">
      <li><strong>Equity signal:</strong> Bangladesh's secondary education system may be effectively neutralizing socio-economic disadvantage at the HSC stage — an achievement worth examining and replicating.</li>
      <li><strong>Ceiling/floor compression:</strong> The dataset shows a 3.00–5.00 HSC range (no failures), which compresses measurable variance. Discriminating factors likely operate below the HSC threshold — i.e., in <em>whether a student reaches HSC at all</em>, not in their HSC score once there.</li>
    </ol>
    Policymakers should therefore focus interventions on <strong>retention and enrollment upstream</strong> rather than on boosting HSC scores among the enrolled.
  </div>
</section>

<!-- ═══ SECTION 4: STUDY BEHAVIOR ═══ -->
<section class="section">
  <h2 class="section-title">4. Study Behavior and Attendance Patterns</h2>
  <p class="section-objective">Correlating student behavioral inputs (study hours, attendance) with HSC outcomes.</p>

  <div class="grid-2">
    <div class="card">
      <h3>HSC Mean by Weekly Study Hours</h3>
      <div class="chart-container"><canvas id="studyHoursChart"></canvas></div>
    </div>
    <div class="card">
      <h3>HSC Mean by Attendance Band</h3>
      <div class="chart-container"><canvas id="attendanceChart"></canvas></div>
    </div>
  </div>

  <div class="card">
    <h3>Key Behavioral Correlations</h3>
    <table>
      <thead><tr><th>Variable</th><th>Mean</th><th>Median</th><th>Correlation with HSC (Pearson r)</th><th>Interpretation</th></tr></thead>
      <tbody>
        <tr><td>Study Hours / Week</td><td>{sb['study_hours_mean']}</td><td>{sb['study_hours_median']}</td><td><strong>{sb['study_corr']}</strong></td><td>Negligible</td></tr>
        <tr><td>Attendance (%)</td><td>{sb['attendance_mean']}</td><td>{sb['attendance_median']}</td><td><strong>{sb['attendance_corr']}</strong></td><td>Negligible</td></tr>
      </tbody>
    </table>
  </div>

  <div class="warning-box">
    <strong>Counter-intuitive finding:</strong> Neither study hours nor attendance meaningfully predict HSC outcomes in this cohort (both |r| &lt; 0.03). The 91–100% attendance band ({sb['att_bin_hsc'][3]['mean_hsc']:.2f}) actually scored slightly <em>lower</em> than the 81–90% band ({sb['att_bin_hsc'][2]['mean_hsc']:.2f}). This suggests attendance reporting may be noisy, or that attendance alone — divorced from quality of instruction — is insufficient to drive academic gains.
  </div>
</section>

<!-- ═══ SECTION 5: REGIONAL DISPARITIES ═══ -->
<section class="section">
  <h2 class="section-title">5. Regional Performance Disparities</h2>
  <p class="section-objective">District-level and institutional comparisons to surface geographic inequities.</p>

  <div class="card">
    <h3>HSC Performance Heatmap by District (sorted high to low)</h3>
    <div style="margin-top:14px">
"""

# Generate heatmap bars for districts
max_hsc = max(x['mean_hsc'] for x in reg['district_hsc'])
min_hsc = min(x['mean_hsc'] for x in reg['district_hsc'])
for row in reg['district_hsc']:
    pct = (row['mean_hsc'] / 5.0) * 100
    # Color based on rank
    norm = (row['mean_hsc'] - min_hsc) / (max_hsc - min_hsc) if max_hsc > min_hsc else 0.5
    # green to amber gradient
    g = int(106 + norm * 60)
    r_c = int(220 - norm * 120)
    color = f"rgb({r_c},{g},78)" if norm > 0.5 else f"rgb({r_c},{g},78)"
    html += f"""
      <div class="heatmap-row">
        <div class="heatmap-label">{row['district']}</div>
        <div class="heatmap-bar"><div class="heatmap-fill" style="width:{pct}%;background:{color}">{row['mean_hsc']:.3f} ({row['count']} students)</div></div>
      </div>"""

html += f"""
    </div>
  </div>

  <div class="grid-2">
    <div class="card">
      <h3>Excellent Performance Rate by District (%)</h3>
      <div class="chart-container tall"><canvas id="excellentDistrictChart"></canvas></div>
    </div>
    <div class="card">
      <h3>GPA Progression Delta by District</h3>
      <div class="chart-container tall"><canvas id="deltaDistrictChart"></canvas></div>
    </div>
  </div>

  <div class="card">
    <h3>Complete District-Level Performance Table</h3>
    <table>
      <thead><tr><th>Rank</th><th>District</th><th>N</th><th>Mean HSC</th><th>Std Dev</th><th>Excellent %</th><th>Progression Δ</th></tr></thead>
      <tbody>"""

for i, row in enumerate(reg['district_hsc'], 1):
    d_name = row['district']
    exc = reg['excellent_by_district'][d_name]
    delta = reg['delta_by_district'][d_name]
    delta_color = '#10b981' if delta >= 0 else '#ef4444'
    html += f"""
        <tr><td>{i}</td><td><strong>{d_name}</strong></td><td>{row['count']}</td><td>{row['mean_hsc']:.3f}</td><td>{row['std_hsc']:.3f}</td><td>{exc}%</td><td style="color:{delta_color};font-weight:600">{delta:+.3f}</td></tr>"""

html += f"""
      </tbody>
    </table>
  </div>

  <div class="grid-2">
    <div class="card">
      <h3>Public vs Private Schools</h3>
      <table>
        <thead><tr><th>School Type</th><th>N</th><th>Mean HSC</th><th>Std Dev</th></tr></thead>
        <tbody>
          <tr><td>Public</td><td>{reg['school_type_hsc'][1]['count']}</td><td><strong>{reg['school_type_hsc'][1]['mean_hsc']:.3f}</strong></td><td>{reg['school_type_hsc'][1]['std_hsc']:.3f}</td></tr>
